    16	/**
    17	 * Translates the JSON scenario protocol into MHPCO operations and back.
    18	 * The protocol field names are binding; the premium rules live in
    19	 * {@link PremiumPolicy}.
    20	 */
    21	public class ClaimOfficeCli {
    22	
    23	    private static final ObjectMapper JSON = new ObjectMapper();
    24	
    25	    private final PriceList priceList = new PriceList();
    26	    private final PremiumPolicy premiumPolicy = new PremiumPolicy(priceList);
    27	    private final ClaimPolicy claimPolicy = new ClaimPolicy();
    28	
    29	    public void run(InputStream scenario, PrintStream results) {
    30	        try {
    31	            JsonNode input = JSON.readTree(scenario);
    32	            int yearsWithMHPCO = input.get("customer").get("yearsWithMHPCO").asInt();
    33	            ObjectNode output = JSON.createObjectNode();
    34	            ArrayNode resultsNode = output.putArray("results");
    35	            int contractsAlreadyHeld = 0;
    36	            Map<Integer, Policy> policiesByQuoteStep = new HashMap<>();
    37	            JsonNode steps = input.get("steps");
    38	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
    39	                JsonNode step = steps.get(stepIndex);
    40	                if ("claim".equals(step.get("op").asText())) {
    41	                    settleClaim(step, policiesByQuoteStep, resultsNode.addObject());
    42	                    continue;
    43	                }
    44	                Customer customer = new Customer(yearsWithMHPCO, contractsAlreadyHeld);
    45	                List<InsuredItem> insuredItems = insuredItems(step);
    46	                policiesByQuoteStep.put(stepIndex, Policy.covering(insuredItems, priceList));
    47	                resultsNode.addObject().put("premium",
    48	                        premiumPolicy.quote(customer, insuredItems));
    49	                contractsAlreadyHeld++;
    50	            }
    51	            results.print(JSON.writeValueAsString(output));
    52	        } catch (IOException e) {
    53	            throw new UncheckedIOException(e);
    54	        }
    55	    }
    56	
    57	    private void settleClaim(JsonNode claimStep, Map<Integer, Policy> policiesByQuoteStep,
    58	            ObjectNode result) {
    59	        Policy policy = policiesByQuoteStep.get(claimStep.get("policy").asInt());
    60	        BigDecimal paid = policy.settle(damages(claimStep), claimPolicy);
    61	        result.put("payout", paid.intValueExact());
    62	        result.put("remainingCap", policy.remainingCap().intValueExact());
    63	    }
    64	
    65	    private static List<Damage> damages(JsonNode claimStep) {
    66	        List<Damage> damages = new ArrayList<>();
    67	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
    68	            damages.add(new Damage(damage.get("itemType").asText(),
    69	                    new BigDecimal(damage.get("amount").asText())));
    70	        }
    71	        return damages;
    72	    }
    73	
    74	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
    75	        List<InsuredItem> items = new ArrayList<>();
    76	        for (JsonNode item : quoteStep.get("items")) {
    77	            items.add(new InsuredItem(item.get("type").asText(),
    78	                    item.path("cursed").asBoolean(false),
    79	                    item.path("enchantment").asInt(0)));
    80	        }
    81	        return items;
    82	    }
    83	}
===== ClaimPolicy.java =====
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO claim rules: what the office reimburses for a damage report against
     5	 * a policy, after the deductible and within the policy's payout cap.
     6	 *
     7	 * A payout is a payment out of the office, so its fraction of a G is rounded in
     8	 * the office's favor by {@link InOfficesFavor}.
     9	 */
    10	public class ClaimPolicy {
    11	
    12	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
    13	    private static final BigDecimal HALF = new BigDecimal("0.5");
    14	
    15	    /**
    16	     * The office reimburses a damage less the deductible, never below nothing.
    17	     * A special clause on the damaged item may first reduce what counts as
    18	     * reimbursable damage.
    19	     */
    20	    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
    21	        BigDecimal reimbursable = underSpecialClauses(damageAmount, damagedItem);
    22	        return InOfficesFavor.payment(
    23	                reimbursable.subtract(DEDUCTIBLE_PER_DAMAGE).max(BigDecimal.ZERO));
    24	    }
    25	
    26	    /** The clauses the office applies to the damage before the deductible. */
    27	    private static BigDecimal underSpecialClauses(BigDecimal damageAmount,
    28	            InsuredItem damagedItem) {
    29	        if (damagedItem.earnsHalfReimbursementOnly()) {
    30	            return damageAmount.multiply(HALF);
    31	        }
    32	        return damageAmount;
    33	    }
    34	}
