     1	/**
     2	 * An item a policy covers, as the office records it.
     3	 *
     4	 * The office reads the recorded facts to classify the item's risk, so the
     5	 * classifications live here with the facts they read, while what each risk
     6	 * costs is the premium rules' business in {@link PremiumPolicy}. The
     7	 * enchantment level carries more than one such classification: the premium
     8	 * rules surcharge a high enchantment from level 5 up, and the claim rules have
     9	 * their own, higher threshold, so each threshold is named for the rule it
    10	 * serves rather than sharing one vague "enchanted" predicate.
    11	 */
    12	public record InsuredItem(String type, boolean cursed, int enchantment) {
    13	
    14	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    15	    private static final int HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
    16	
    17	    /**
    18	     * The office counts an item as highly enchanted, and so as carrying a risk
    19	     * worth a surcharge, from enchantment level 5 up.
    20	     */
    21	    public boolean isHighlyEnchanted() {
    22	        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
    23	    }
    24	
    25	    /**
    26	     * From enchantment level 8 up the office considers damage too unruly to
    27	     * reimburse in full and reimburses only half of it.
    28	     */
    29	    public boolean earnsHalfReimbursementOnly() {
    30	        return enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
    31	    }
    32	}
===== Policy.java =====
     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	
     4	/**
     5	 * A policy the office has written: the items it covers and how much of its
     6	 * payout cap is left. The cap is twice the insurance sum and is not raised by
     7	 * premium modifiers.
     8	 *
     9	 * Settling an incident against the policy is this policy's decision, not the
    10	 * protocol's: the office reimburses every reported damage on its own terms (the
    11	 * {@link ClaimPolicy} states what one damage earns) and pays out only what the
    12	 * cap still allows, so the deductible is borne once per damage reported and the
    13	 * cap is consumed in the order the damages are reported.
    14	 */
    15	public class Policy {
    16	
    17	    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");
    18	
    19	    private final List<InsuredItem> insuredItems;
    20	    private BigDecimal remainingCap;
    21	
    22	    /**
    23	     * The office writes a policy over the items a customer brings: what it
    24	     * insures them for is the {@link PriceList}'s to state, and the cap that
    25	     * insurance sum earns is this policy's own rule. Premium modifiers are no
    26	     * part of it, which is why the policy is written from the covered items and
    27	     * never from the premium quoted for them.
    28	     */
    29	    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
    30	        return new Policy(insuredItems, priceList.insuranceSum(insuredItems));
    31	    }
    32	
    33	    private Policy(List<InsuredItem> insuredItems, BigDecimal insuranceSum) {
    34	        this.insuredItems = List.copyOf(insuredItems);
    35	        this.remainingCap = insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM);
    36	    }
    37	
    38	    /**
    39	     * What the office pays for one reported incident: every damage reimbursed on
    40	     * its own terms, the total limited to the cap the policy has left.
    41	     */
    42	    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
    43	        BigDecimal paid = BigDecimal.ZERO;
    44	        for (Damage damage : damages) {
    45	            paid = paid.add(payWithinCap(
    46	                    claimPolicy.reimbursementFor(damage.amount(), damagedItem(damage))));
    47	        }
    48	        return paid;
    49	    }
    50	
    51	    /** The covered item a reported damage is about, which the clauses are read from. */
    52	    private InsuredItem damagedItem(Damage damage) {
    53	        for (InsuredItem insuredItem : insuredItems) {
    54	            if (insuredItem.type().equals(damage.itemType())) {
    55	                return insuredItem;
    56	            }
    57	        }
    58	        throw new IllegalArgumentException(
    59	                "the policy does not cover a " + damage.itemType());
    60	    }
    61	
    62	    /** Pays what the cap still allows and records the rest as exhausted. */
    63	    private BigDecimal payWithinCap(BigDecimal desiredPayout) {
    64	        BigDecimal paid = desiredPayout.min(remainingCap);
    65	        remainingCap = remainingCap.subtract(paid);
    66	        return paid;
    67	    }
    68	
    69	    public BigDecimal remainingCap() {
    70	        return remainingCap;
    71	    }
    72	}
