     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	
     4	/**
     5	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
     6	 * fee, applied to the base premium the {@link PriceList} states for the insured
     7	 * items.
     8	 *
     9	 * A premium is a charge to the customer, so its fraction of a G is rounded in
    10	 * the office's favor by {@link InOfficesFavor}.
    11	 */
    12	public class PremiumPolicy {
    13	
    14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
    15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
    16	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
    17	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
    18	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
    19	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
    20	
    21	    private final PriceList priceList;
    22	
    23	    /** The premium rules read their base premiums from the office's price list. */
    24	    public PremiumPolicy(PriceList priceList) {
    25	        this.priceList = priceList;
    26	    }
    27	
    28	    /**
    29	     * The office charges both kinds of modifier on a base premium, never on each
    30	     * other: an item modifier on the affected item's own base premium, a
    31	     * policy-wide modifier on the policy base premium. So the two are summed
    32	     * alongside the base premium rather than compounded in sequence, and the
    33	     * processing fee is added at the very end.
    34	     */
    35	    public int quote(Customer customer, List<InsuredItem> insuredItems) {
    36	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
    37	        BigDecimal premium = policyBasePremium
    38	                .add(itemRiskSurcharges(insuredItems))
    39	                .add(policyWideModifiers(policyBasePremium, customer))
    40	                .add(PROCESSING_FEE);
    41	        return InOfficesFavor.charge(premium).intValueExact();
    42	    }
    43	
    44	    /**
    45	     * Item-scope modifiers: each is charged on the base premium of the affected
    46	     * item alone, so a modifier on one item never touches another item's share
    47	     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
    48	     * business; this rule only states that the policy owes the sum of them.
    49	     */
    50	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
    51	        BigDecimal surcharges = BigDecimal.ZERO;
    52	        for (InsuredItem insuredItem : insuredItems) {
    53	            surcharges = surcharges.add(riskSurcharge(insuredItem));
    54	        }
    55	        return surcharges;
    56	    }
    57	
    58	    /**
    59	     * What the risks the office reads in one item cost, charged on that item's
    60	     * own base premium. A curse and a high enchantment are separate risks, so an
    61	     * item carrying both is surcharged for both rather than letting the graver
    62	     * risk absorb the other.
    63	     */
    64	    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
    65	        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
    66	        BigDecimal surcharge = BigDecimal.ZERO;
    67	        if (insuredItem.cursed()) {
    68	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
    69	        }
    70	        if (insuredItem.isHighlyEnchanted()) {
    71	            surcharge = surcharge.add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
    72	        }
    73	        return surcharge;
    74	    }
    75	
    76	    /**
    77	     * Policy-scope modifiers: each is charged on the policy base premium, the
    78	     * sum of all item base premiums. Every quote is a first insurance of the
    79	     * items it covers, whatever the customer's history.
    80	     */
    81	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
    82	        return firstInsuranceSurcharge(policyBasePremium)
    83	                .subtract(loyaltyDiscount(policyBasePremium, customer))
    84	                .subtract(followUpContractDiscount(policyBasePremium, customer));
    85	    }
    86	
    87	    /**
    88	     * Every contract after the customer's first earns a discount, however long
    89	     * they have been with the office.
    90	     */
    91	    private static BigDecimal followUpContractDiscount(BigDecimal policyBasePremium,
    92	            Customer customer) {
    93	        if (!customer.holdsFollowUpContract()) {
    94	            return BigDecimal.ZERO;
    95	        }
    96	        return policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
    97	    }
    98	
    99	    /**
   100	     * Every quote is a first insurance of the items it covers, whatever the
   101	     * customer's history, so this surcharge is charged on every policy.
   102	     */
   103	    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
   104	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
   105	    }
   106	
   107	    /**
   108	     * The office rewards a long-standing customer with a discount on the policy
   109	     * base premium. Who counts as long-standing is the customer's standing to
   110	     * answer; this rule only states what that standing is worth.
   111	     */
   112	    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
   113	        if (!customer.isLongStanding()) {
   114	            return BigDecimal.ZERO;
   115	        }
   116	        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
   117	    }
   118	}
===== PriceList.java =====
     1	import java.math.BigDecimal;
     2	import java.util.LinkedHashMap;
     3	import java.util.List;
     4	import java.util.Map;
     5	import java.util.Set;
     6	
     7	/**
     8	 * The MHPCO price list: one published tariff row per insurable item type,
     9	 * stating what the office charges as that item's base premium and what it
    10	 * insures the item for. Main items are listed individually; every component
    11	 * shares one row, because the office prices and insures a rune exactly as it
    12	 * does a moonstone, and a building block of alike components is offered at a
    13	 * special rate.
    14	 *
    15	 * The block rate is the one tariff decision that is not a property of a single
    16	 * item: a block is a quantity of <em>alike</em> components, so the tariff also
    17	 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
    18	 * them before pricing.
    19	 *
    20	 * This is the office's tariff. It changes on its own schedule, independently of
    21	 * the modifier rules in {@link PremiumPolicy}.
    22	 */
    23	public class PriceList {
    24	
    25	    /**
    26	     * What the office charges and insures for one item type. The two figures
    27	     * are revised on their own schedules — a rate revision repricing premiums
    28	     * need not revalue the items — but they are published together, as one row
    29	     * of the price list, because they describe the same insured thing.
    30	     */
    31	    private record Tariff(BigDecimal basePremium, BigDecimal insuranceValue) {
    32	    }
    33	
    34	    /** Every component is charged and insured alike, whatever its type. */
    35	    private static final Tariff COMPONENT_TARIFF =
    36	            new Tariff(new BigDecimal("25"), new BigDecimal("250"));
    37	
    38	    /** The published price list: the item types the office insures, and at what. */
    39	    private static final Map<String, Tariff> TARIFF = Map.of(
    40	            "sword", new Tariff(new BigDecimal("100"), new BigDecimal("1000")),
    41	            "amulet", new Tariff(new BigDecimal("60"), new BigDecimal("600")),
    42	            "staff", new Tariff(new BigDecimal("80"), new BigDecimal("800")),
    43	            "potion", new Tariff(new BigDecimal("40"), new BigDecimal("400")),
    44	            "rune", COMPONENT_TARIFF,
    45	            "moonstone", COMPONENT_TARIFF);
    46	
    47	    /**
    48	     * Which of the insured types the office regards as components rather than
    49	     * main items. Only the block offer asks: a component's own figures are read
    50	     * from its tariff row like any other item's.
    51	     */
    52	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
    53	
    54	    /** A building block of exactly 3 alike components is offered at this rate. */
    55	    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
    56	    private static final int COMPONENT_BLOCK_SIZE = 3;
    57	
    58	    /**
    59	     * The insurance sum of a policy: the sum of its items' insurance values. A
    60	     * block discount is a premium offer and does not lower the insurance sum.
    61	     */
    62	    public BigDecimal insuranceSum(List<InsuredItem> insuredItems) {
    63	        BigDecimal total = BigDecimal.ZERO;
    64	        for (InsuredItem insuredItem : insuredItems) {
    65	            total = total.add(TARIFF.get(insuredItem.type()).insuranceValue());
    66	        }
    67	        return total;
    68	    }
    69	
    70	    /** The base premium for all items a policy covers, alike items priced together. */
    71	    public BigDecimal policyBasePremium(List<InsuredItem> insuredItems) {
    72	        BigDecimal total = BigDecimal.ZERO;
    73	        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItems).entrySet()) {
    74	            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
    75	        }
    76	        return total;
    77	    }
    78	
    79	    /**
    80	     * The base premium of one insured item on its own, which is what an
    81	     * item-specific surcharge such as the curse surcharge is charged on. A
    82	     * component priced within a block is not charged on its own.
    83	     */
    84	    public BigDecimal basePremium(InsuredItem insuredItem) {
    85	        return basePremium(insuredItem.type(), 1);
    86	    }
    87	
    88	    private static Map<String, Integer> groupedByAlikeness(List<InsuredItem> insuredItems) {
    89	        Map<String, Integer> counts = new LinkedHashMap<>();
    90	        for (InsuredItem insuredItem : insuredItems) {
    91	            counts.merge(alikenessGroupOf(insuredItem.type()), 1, Integer::sum);
    92	        }
    93	        return counts;
    94	    }
    95	
    96	    /**
    97	     * The office counts two items as alike when they are of exactly the same
    98	     * type, not merely of the same family: 2 runes and a moonstone are three
    99	     * loose components priced at 75 G, never a block, because a moonstone is not
   100	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
   101	     * returning a family name here instead of the type itself.
   102	     */
   103	    private static String alikenessGroupOf(String itemType) {
   104	        return itemType;
   105	    }
   106	
   107	    /**
   108	     * What a holding of alike items of one type costs: the type's own rate per
   109	     * item, except that a block of components is offered at the block rate.
   110	     */
   111	    private static BigDecimal basePremium(String itemType, int count) {
   112	        if (qualifiesForBlockRate(itemType, count)) {
   113	            return COMPONENT_BLOCK_BASE_PREMIUM;
   114	        }
   115	        return TARIFF.get(itemType).basePremium().multiply(BigDecimal.valueOf(count));
   116	    }
   117	
   118	    /**
   119	     * The office grants the block rate only to a holding of exactly 3 alike
   120	     * components. It neither prices a part of a block at the block rate (4
   121	     * components are not a block) nor breaks a larger holding down into blocks
   122	     * (7 components are priced as 7, not as two blocks and one loose component).
   123	     * Main items are never blocked: 3 swords are 3 swords.
   124	     */
   125	    private static boolean qualifiesForBlockRate(String itemType, int alikeItemCount) {
   126	        return COMPONENT_TYPES.contains(itemType) && alikeItemCount == COMPONENT_BLOCK_SIZE;
   127	    }
   128	}

