    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
        BigDecimal paid = BigDecimal.ZERO;
        for (Damage damage : damages) {
            paid = paid.add(payWithinCap(
                    claimPolicy.reimbursementFor(damage.amount(), coveredItemFor(damage))));
        }
        return paid;
    }

    /**
     * The covered item whose terms a reported damage is settled on: the office
     * looks the reported kind of item up among the items this policy covers, and
     * reads the clauses from it. A damage naming a kind of item the policy does
     * not cover is no claim the office will settle.
     *
     * The office matches by the kind of item reported, which is all a single
     * covered item of a kind needs. Counting a policy's several items of one
     * kind against the damages reported for that kind is a separate decision the
     * office has not been asked to make yet.
     */
    private InsuredItem coveredItemFor(Damage damage) {
        for (InsuredItem insuredItem : insuredItems) {
            if (insuredItem.type().equals(damage.itemType())) {
                return insuredItem;
            }
        }
        throw new IllegalArgumentException(
                "the policy does not cover a " + damage.itemType());
    }

    /** Pays what the cap still allows and records the rest as exhausted. */
    private BigDecimal payWithinCap(BigDecimal desiredPayout) {
        BigDecimal paid = desiredPayout.min(remainingCap);
        remainingCap = remainingCap.subtract(paid);
        return paid;
    }

    public BigDecimal remainingCap() {
        return remainingCap;
    }
}
